    ('BIOC-B 880', 'RESEARCH: BIOCHEMISTRY', '6829', 'Class Status', NULL, NULL, 'Matt Bochman, Celeste Nicola', 18, NULL, 'Laboratory', '10.5', NULL, ARRAY[]::TEXT[], 'Thesis research for graduate biochemistry students.', ARRAY[]::TEXT[], NULL),
    ('BIOC-B 880', 'RESEARCH: BIOCHEMISTRY', '6830', 'Class Status', NULL, NULL, 'Matt Bochman, Celeste Nicola', 19, NULL, 'Laboratory', '10.5', NULL, ARRAY[]::TEXT[], 'Thesis research for graduate biochemistry students.', ARRAY[]::TEXT[], NULL),
