    ('BIOL-M 250', 'MICROBIOLOGY', '4245', 'Closed', 'MWF Monday, Wednesday, Friday 12:45 PM–1:35 PM', 'MO 007', 'Irene Newton', 0, NULL, 'Lecture', '3', 'MORRISON HALL', ARRAY[]::TEXT[], 'Application of fundamental principles to the study of microorganisms. Significance of microorganisms to humans and their environment. Does not count as an upper-level lecture in the Biology B.A. major or Biology B.S. degree.', ARRAY['COLL (CASE) N&M Breadth of Inquiry credit'], NULL),
    ('BIOL-M 315', 'MICROBIOLOGY LABORATORY', '6237', 'Class Status', 'M Monday 12:45 PM–5:10 PM', 'JH 122A', 'Carl Kulow', 1, NULL, 'Laboratory', '2', 'BIOLOGY BUILDING', ARRAY[]::TEXT[], 'A conventional laboratory of exercises, demonstrations and discussions. The goal is to achieve proficiency in the principles and techniques necessary for the manipulation of microorganisms under aseptic conditions.', ARRAY['Class uses IU eTexts'], NULL),
