    ('CHEM-X 373', 'PROFESSIONAL PRACTICE IN CHEMISTRY', '7226', 'Class Status', NULL, NULL, 'Martha Oakley', 10, NULL, 'Lecture', '1–6', NULL, ARRAY[]::TEXT[], 'Designed to provide opportunities for students to receive credit for career-related, full-time work.', ARRAY[]::TEXT[], NULL),
    ('CHEM-X 399', 'CHEMICAL RESEARCH', '7225', 'Class Status', NULL, NULL, 'David Williams', 17, NULL, 'Research', '0–3', NULL, ARRAY[]::TEXT[], 'Provides students an opportunity to perform research in an IU Chemistry Department lab. Written research thesis is required. Cannot be used as a substitute for other chemistry courses.', ARRAY[]::TEXT[], NULL),
    ('CHEM-X 499', 'CHEMICAL RESEARCH CAPSTONE', '4698', 'Class Status', NULL, NULL, 'David Williams', 23, NULL, 'Research', '2', NULL, ARRAY[]::TEXT[], 'For outstanding students in research. May be used to satisfy upper-level laboratory hour requirements in the B.S. major; may not be used in fulfillment of chemistry major hours in a B.A. major. A written research thesis with oral presentation is required.', ARRAY['COLL INTENSIVE WRITING SECTIONS'], NULL),
    ('CJUS-G 901', 'ADVANCED RESEARCH', '1314', 'Class Status', NULL, NULL, 'Miriam Northcutt Bohmert', 4, NULL, 'Research', '6', NULL, ARRAY[]::TEXT[], 'Available to graduate students who have completed all course requirements for their doctorates, have passed doctoral qualifying examinations, and have the requisite number of degree credit hours, this course provides the advanced research student with a forum for sharing ideas and problems under the supervision of a senior researcher.', ARRAY[]::TEXT[], NULL),
