    ('COGS-X 373', 'INTERNSHIP IN PROFESSIONAL PRACTICE', '1368', 'Class Status', NULL, NULL, 'Erica Cartmill', 10, NULL, 'Practice', '1–6', NULL, ARRAY[]::TEXT[], 'Professional work experience in an industry or research organization setting, using skills/knowledge acquired in cognitive science coursework. Requires learning contract. Evaluation by site supervisor and Cognitive Science Program.', ARRAY[]::TEXT[], NULL),
    ('COGS-X 490', 'READINGS IN THE COGNITIVE AND INFORMATION SCIENCES', '1369', 'Class Status', NULL, NULL, 'Erica Cartmill', 9, NULL, 'Research', '1–3', NULL, ARRAY[]::TEXT[], 'Tutorial study in specialized topics of the cognitive and information sciences.', ARRAY[]::TEXT[], NULL),
    ('COGS-X 497', 'RESEARCH IN COGNITIVE AND INFORMATION SCIENCE', '1366', 'Class Status', NULL, NULL, 'Erica Cartmill', 11, NULL, 'Research', '1–3', NULL, ARRAY[]::TEXT[], 'Active participation in research under faculty supervision.', ARRAY[]::TEXT[], NULL),
    ('COGS-X 497', 'RESEARCH IN COGNITIVE AND INFORMATION SCIENCE', '7637', 'Class Status', NULL, NULL, 'Erica Cartmill', 10, NULL, 'Research', '1–3', NULL, ARRAY[]::TEXT[], 'Active participation in research under faculty supervision.', ARRAY[]::TEXT[], NULL),
    ('COGS-X 498', 'PROJECT IN COGNITIVE AND INFORMATION SCIENCES', '1367', 'Class Status', NULL, NULL, 'Erica Cartmill', 10, NULL, 'Research', '1–3', NULL, ARRAY[]::TEXT[], 'The student will conduct a research project in the cognitive and information sciences: either by designing, conducting, and analyzing an independent experiment; by developing and testing a computer simulation of some aspect of cognition; or by otherwise engaging in a program of original research. Projects must be approved in advance and supervised along the way by the instructor.', ARRAY[]::TEXT[], NULL),
    ('COLL-C 103', 'CRITICAL APPROACHES TO THE ARTS AND HUMANITIES', '13379', 'Class Status', 'MW Monday, Wednesday 3:10 PM–4:00 PM', 'WY 005', 'Robin Reames', 1, 'Lecture', 'Lecture', '3', 'WYLIE HALL', ARRAY[]::TEXT[], 'Specific topics will vary by section and over time, but all versions of C103 will meet the objectives of the College of Arts and Sciences Critical Approaches curriculum. The curriculum is intended for freshmen and sophomores, who will learn how scholars from the arts and humanities Breadth of Inquiry area frame questions, propose answers, and assess the validity of competing approaches. Writing and related skills are stressed.', ARRAY['IUB GenEd A&H credit
COLL (CASE) A&H Breadth of Inquiry credit'], NULL),
