    ('CSCI-A 216', 'DIGITAL MULTIMEDIA CONCEPTS AND TECHNOLOGIES', '10063', 'Class Status', 'MW Monday, Wednesday 11:35 AM–12:25 PM', 'GY 1032', 'Jeff Whitmer', 12, 'Lecture', 'Lecture', '3', 'GEOLOGICAL SCIENCES', ARRAY[]::TEXT[], 'In-depth introduction to the technologies of digital hardware and software relevant to efficient multimedia communication methods. Lectures focus on computational foundations, underlying concepts, and digital methods. Laboratory provides direct experience with concepts presented in lecture, using latest available digital tools to create direct and web-based multimedia content. Lecture and laboratory.', ARRAY[]::TEXT[], NULL),
    ('CSCI-A 216', 'DIGITAL MULTIMEDIA CONCEPTS AND TECHNOLOGIES', '10064', 'Class Status', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'IF 0006', 'Staff', 12, 'Laboratory', 'Lecture', '3', 'GEOLOGICAL SCIENCES', ARRAY[]::TEXT[], 'In-depth introduction to the technologies of digital hardware and software relevant to efficient multimedia communication methods. Lectures focus on computational foundations, underlying concepts, and digital methods. Laboratory provides direct experience with concepts presented in lecture, using latest available digital tools to create direct and web-based multimedia content. Lecture and laboratory.', ARRAY[]::TEXT[], NULL),
