    ('DSCI-D 590', 'TOPICS IN DATA SCIENCE', '34090', 'Class Status', NULL, 'WB WEB', 'Shabnam Kavousian', 23, NULL, 'Lecture', '3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'Emphasis on new developments and research in Data Science.', ARRAY['Class uses IU eTexts'], NULL),
    ('DSCI-D 590', 'TOPICS IN DATA SCIENCE', '36808', 'Class Status', NULL, 'WB WEB', 'Tianhao Mao', 37, NULL, 'Lecture', '3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'Emphasis on new developments and research in Data Science.', ARRAY['Class uses IU eTexts'], NULL),
    ('DSCI-D 591', 'GRADUATE INTERNSHIP', '8289', 'Class Status', NULL, NULL, 'Patrick Shih, Rebekah Sinders', 45, NULL, 'Internship', '0–3', NULL, ARRAY[]::TEXT[], 'Students gain professional work experience in an industry or research organization setting using skills and knowledge acquired in Data Science coursework. A written report will be required upon completion of the experience.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 591', 'GRADUATE INTERNSHIP', '12669', 'Class Status', NULL, NULL, 'Patrick Shih, Jasynda Radanovich, Rebekah Sinders', 27, NULL, 'Internship', '0–3', NULL, ARRAY[]::TEXT[], 'Students gain professional work experience in an industry or research organization setting using skills and knowledge acquired in Data Science coursework. A written report will be required upon completion of the experience.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 591', 'GRADUATE INTERNSHIP', '14513', 'Class Status', NULL, NULL, 'Patrick Shih, Rebekah Sinders', 22, NULL, 'Internship', '0–3', NULL, ARRAY[]::TEXT[], 'Students gain professional work experience in an industry or research organization setting using skills and knowledge acquired in Data Science coursework. A written report will be required upon completion of the experience.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 592', 'DATA SCIENCE IN PRACTICE', '36387', 'Class Status', NULL, 'WB WEB', 'David Wild', 1, NULL, 'Lecture', '3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'Students are organized into teams to carry out real world projects in conjunction with project sponsors, while learning about methodologies for data science consulting.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 595', 'DATA SCIENCE ON-RAMP', '35756', 'Class Status', NULL, 'WB WEB', 'Nasim Anousheh', 20, NULL, 'Lecture', '1–3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'The Data Science On-Ramp contains a series of self-paced modules to build and enhance your data science skill set, oftentimes demanded or desired in data science related jobs. Each module is equal to one (1) credit hour. As such, the Data Science On-Ramp course has variable credit hours.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 595', 'DATA SCIENCE ON-RAMP', '35757', 'Class Status', NULL, 'WB WEB', 'Nasim Anousheh', 22, NULL, 'Lecture', '1–3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'The Data Science On-Ramp contains a series of self-paced modules to build and enhance your data science skill set, oftentimes demanded or desired in data science related jobs. Each module is equal to one (1) credit hour. As such, the Data Science On-Ramp course has variable credit hours.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 699', 'GRADUATE INDEPENDENT STUDY IN DATA SCIENCE', '8290', 'Class Status', NULL, NULL, 'Patrick Shih, Rebekah Sinders', 4, NULL, 'Independent Study', '1–6', NULL, ARRAY[]::TEXT[], 'Independent Study under the direction of a faculty member, culminating in a written report and/or database development and/or documented laboratory experience.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 699', 'GRADUATE INDEPENDENT STUDY IN DATA SCIENCE', '8291', 'Class Status', NULL, NULL, 'Patrick Shih, Rebekah Sinders', 10, NULL, 'Independent Study', '1–6', NULL, ARRAY[]::TEXT[], 'Independent Study under the direction of a faculty member, culminating in a written report and/or database development and/or documented laboratory experience.', ARRAY[]::TEXT[], NULL),
    ('DSCI-D 699', 'GRADUATE INDEPENDENT STUDY IN DATA SCIENCE', '11905', 'Class Status', NULL, NULL, 'Jasynda Radanovich, Patrick Shih, Rebekah Sinders', 9, NULL, 'Independent Study', '1–6', NULL, ARRAY[]::TEXT[], 'Independent Study under the direction of a faculty member, culminating in a written report and/or database development and/or documented laboratory experience.', ARRAY[]::TEXT[], NULL),
    ('EALC-C 101', 'ELEMENTARY CHINESE 1', '3741', 'Class Status', 'TuTh Tuesday, Thursday 10:25 AM–11:15 AM', 'BH 238', 'Xiang Lyu, Ya Wen Tsai', 10, 'Lecture', 'Lecture', '4', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'An introductory course that lays groundwork for the study of modern Chinese. It aims at fostering proficiency in all four language skills (aural understanding, speaking, reading, and writing), and helping students handle simple tasks in daily routines. Basic sentence patterns, vocabulary, and characters are all practiced in meaningful contexts.', ARRAY['IUB GenEd World Language class'], NULL),
