    ('HISP-S 251', 'INTERMEDIATE SPANISH FOR HERITAGE SPEAKERS', '11376', 'Class Status', 'MWF Monday, Wednesday, Friday 9:10 AM–10:00 AM', 'BH 332', 'Israel Herrera', 11, NULL, 'Drill', '3', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'An intermediate language course designed for heritage students, who grew up speaking/hearing Spanish at home or in their communities. Focuses on the practicing of Spanish across modalities, discussing identity aspects, and exploring social and historical context.', ARRAY['IUB GenEd World Language class'], NULL),
    ('HISP-S 251', 'INTERMEDIATE SPANISH FOR HERITAGE SPEAKERS', '11401', 'Class Status', 'MWF Monday, Wednesday, Friday 12:45 PM–1:35 PM', 'GA 0005', 'Israel Herrera', 9, NULL, 'Drill', '3', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'An intermediate language course designed for heritage students, who grew up speaking/hearing Spanish at home or in their communities. Focuses on the practicing of Spanish across modalities, discussing identity aspects, and exploring social and historical context.', ARRAY['IUB GenEd World Language class'], NULL),
    ('HISP-S 280', 'SPANISH GRAMMAR IN CONTEXT', '4453', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'BH 139', 'Gibran Delgado-Diaz', 1, NULL, 'Drill', '3', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'A topic-based approach to the formal aspects of Spanish grammar. Formal linguistics skills are developed through explicit grammar instruction, the reading of Hispanic texts, and the study of literature and culture through writing and conversation.', ARRAY['Class uses IU eTexts'], NULL),
