    ('LING-L 499', 'HONORS PROJECT', '5378', 'Class Status', NULL, NULL, 'Malgorzata Cavar', 10, NULL, 'Independent Study', '1–4', NULL, ARRAY[]::TEXT[], NULL, ARRAY[]::TEXT[], NULL),
    ('LING-L 499', 'HONORS PROJECT', '5379', 'Class Status', NULL, NULL, 'Barbara Vance', 10, NULL, 'Independent Study', '1–4', NULL, ARRAY[]::TEXT[], NULL, ARRAY[]::TEXT[], NULL),
    ('LING-L 499', 'HONORS PROJECT', '6573', 'Class Status', NULL, NULL, 'Kelly Berkson', 10, NULL, 'Independent Study', '1–4', NULL, ARRAY[]::TEXT[], NULL, ARRAY[]::TEXT[], NULL),
