    ('LTAM-Q 101', 'ELEMENTARY QUECHUA I', '3714', 'Class Status', 'TuTh Tuesday, Thursday 9:00 AM–11:00 AM', 'WB WEB', 'Staff', 4, NULL, 'Lecture', '4', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'Introduction to Quechua, spoken by over 13 million people across the Andean Nation of South America; basic grammar and vocabulary; an introduction to the culture and history of the Andean region.', ARRAY['IUB GenEd World Language class'], NULL),
    ('LTAM-Q 201', 'INTERMEDIATE QUECHUA I', '8630', 'Class Status', 'MW Monday, Wednesday 9:50 AM–11:50 AM', 'WB WEB', 'Staff', 1, NULL, 'Lecture', '3', 'WEB-BASED CLASS', ARRAY[]::TEXT[], 'Focuses on more advanced grammatical constructions, vocabulary building, conversational drills, reading, and writing Quechua texts.', ARRAY['IUB GenEd World Language class'], NULL),
