    ('MATH-S 403', 'HONORS CRSE IN MOD ALGEBRA 1', '2185', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–12:25 PM', 'SW 103', 'Valery Lunts', 1, NULL, 'Lecture', '3', 'SWAIN WEST', ARRAY[]::TEXT[], 'Theory of groups, rings, integral domains, fields, and modules.', ARRAY[]::TEXT[], NULL),
    ('MATH-S 413', 'HONORS COURSE IN ANALYSIS I', '3088', 'Class Status', 'MWF Monday, Wednesday, Friday 11:35 AM–12:25 PM', 'SE 010', 'Ciprian Demeter', 4, NULL, 'Lecture', '3', 'SWAIN EAST', ARRAY[]::TEXT[], 'Differentiable transformations defined on Euclidean space, inverse and implicit function theorems. Lebesque integration over Euclidean space and transformation of integrals. Exterior algebra, measure and integration on manifolds. Stokes'' theorem. Closed and exact forms.', ARRAY[]::TEXT[], NULL),
