    ('MUS-M 407', 'SURVEY OF ORGAN LITERATURE AND PERFORMANCE PRACTICE I', '35529', 'Class Status', 'M Monday 4:20 PM–6:00 PM', 'MA 406 MA 406', 'Sarah Stamey', 10, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'A survey of the organ, its literature, and associated performance practices from the Classical period to the present day.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 410', 'COMPOSER OR TOPIC', '7301', 'Class Status', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'SM 242', 'Kristina Muxfeldt', 2, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Aspects of music history, literature, and context related to specific repertories, genres, styles, analysis of characteristic works, performance practices/traditions, historiography, or criticism. May be repeated for different composers or topics.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 413', 'TOPICS IN LATIN AMERICAN MUSIC', '8085', 'Class Status', 'MWF Monday, Wednesday, Friday 10:25 AM–11:15 AM', 'MA 006', 'Wayne Wallace', 5, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'An in-depth survey of particular art music, popular and/or traditional repertoires, ranging from the colonial period to the twenty-first century. Specific content varies with instructor''s area of specialization. Activities outside of class may be scheduled.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 415', 'INTERPRETING UNACCOMPANIED BACH', '10949', 'Closed', 'TuTh Tuesday, Thursday 10:25 AM–11:15 AM', 'MU 205', 'Ingrid Matthews', 0, NULL, 'Lecture', '2', 'MERRILL HALL', ARRAY[]::TEXT[], 'Study and performance of the unaccompanied works by J.S. Bach for violin, cello and flute. Consideration of structural musical elements based on autograph manuscripts. Open to all instrumentalist other than keyboard players.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 431', 'SONG LITERATURE I', '2397', 'Closed', 'MWF Monday, Wednesday, Friday 10:25 AM–11:15 AM', 'MA 007', 'Brian Horne, Sam Witmer', 0, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'Introductory survey of representative non-operatic solo vocal repertoire of the United States, the British Isles, Italy, Germany, Austria, and France. Techniques and application of song study, musicianship, interpretation, performance practice, and program building.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 435', 'PERFORMANCE PRACTICES BEFORE 1750', '8402', 'Closed', 'MW Monday, Wednesday 10:10 AM–11:00 AM', 'MU 204', 'Joanna Blendulf', 0, NULL, 'Lecture', '2', 'MERRILL HALL', ARRAY[]::TEXT[], 'Medieval, Renaissance, and Baroque repertory studied in light of historical performance procedures, instruments, tuning, rhythm, notations, and other theoretical areas of importance for performance. Some consideration is given to the recreation of historical music employing modern instruments.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 458', 'TOPICS IN HISTORICAL PERFORMANCE', '34740', 'Class Status', 'Th Thursday 12:45 PM–2:25 PM', 'MA 452', 'Hsuan Chang Kitano', 1, NULL, 'Lecture', '2', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'Variable topics in repertory and performance practice in the field of historical performance. May be taken more than once.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 469', 'SEMINAR IN STRING QUARTET LITERATURE', '10439', 'Class Status', 'Tu Tuesday 12:45 PM–2:00 PM', 'JS 315', 'Simin Ganatra', 12, NULL, 'Lecture', '2', 'EAST STUDIO BUILDING', ARRAY[]::TEXT[], 'Performance-based survey of chamber music literature from Haydn to the present. Six seminal works covered each semester.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 501', 'PROSEMINAR IN MUSIC HISTORY AND LITERATURE', '6624', 'Closed', 'MWF Monday, Wednesday, Friday 9:10 AM–10:00 AM', 'SM 340', 'Jennifer Saltzstein, Jacqueline Fortier', 0, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'An introduction to the graduate study of music history and literature.', ARRAY[]::TEXT[], NULL),
