    ('MUS-M 510', 'TOPICS IN MUSIC LITERATURE', '15058', 'Closed', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'RA B111', 'Jacquelyn Sholes', 0, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Aspects of music history, literature, and context related to specific repertories, genres, styles, analysis of characteristic works, performance practices/traditions, historiography, or criticism. May be repeated for different topics.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 513', 'TOPICS IN LATIN AMERICAN MUSIC', '8271', 'Class Status', 'MWF Monday, Wednesday, Friday 10:25 AM–11:15 AM', 'MA 006', 'Wayne Wallace', 5, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'An in-depth survey of particular art music, popular and/or traditional repertoires, ranging from the colonial period to the twenty-first century. Specific content varies with instructor''s area of specialization. Open to majors and non-majors. Activities outside of class may be scheduled and a final research project is required.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 515', 'INTERPRETING UNACCOMPANIED BACH', '10950', 'Closed', 'TuTh Tuesday, Thursday 10:25 AM–11:15 AM', 'MU 205', 'Ingrid Matthews', 0, NULL, 'Lecture', '2', 'MERRILL HALL', ARRAY[]::TEXT[], 'Study and performance of the unaccompanied works by J.S. Bach for violin, cello and flute. Consideration of structural musical elements based on autograph manuscripts. Open to all instrumentalist other than keyboard players.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 519', 'BAROQUE PERFORMANCE PRACTICE', '15033', 'Class Status', 'WF Wednesday, Friday 10:25 AM–11:15 AM', 'MU 205', 'Dana Marsh', 5, NULL, 'Lecture', '2', 'MERRILL HALL', ARRAY[]::TEXT[], 'The basic literature of the Baroque period with performance-oriented analysis, survey of original sources, and study of performance-related theoretical works.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 523', 'MUSIC AND RHETORIC IN PERFORMANCE', '9465', 'Class Status', 'TuTh Tuesday, Thursday 10:25 AM–11:15 AM', 'MU 204', 'Dana Marsh', 2, NULL, 'Lecture', '2', 'MERRILL HALL', ARRAY[]::TEXT[], 'This course deals with changing relationships between words and music (c.1300-1750) through the evidence of contemporaneous ideologies applied to composition, interpretation and performance. Beginning with classical authors who prescribe techniques for persuasive oration, the reception of such principles within both the Renaissance and Baroque periods will be given central emphasis.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 525', 'SURVEY OF OPERATIC LITERATURE', '6473', 'Closed', 'MW Monday, Wednesday 11:10 AM–12:25 PM', 'SM 267', 'Giovanni Zanovello', 0, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Emphasis on the eighteenth and nineteenth centuries.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 527', 'SYMPHONIC LITERATURE', '6474', 'Closed', 'TuTh Tuesday, Thursday 11:10 AM–12:25 PM', 'SM 267', 'Jacquelyn Sholes', 0, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Orchestral music of the eighteenth and nineteenth centuries.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 528', 'CHAMBER MUSIC LITERATURE', '13010', 'Class Status', 'MW Monday, Wednesday 11:10 AM–12:25 PM', 'MA 454', 'Bess Liu', 1, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'Emphasis on eighteenth and nineteenth centuries', ARRAY[]::TEXT[], NULL),
    ('MUS-M 531', 'SONG LITERATURE III', '2398', 'Closed', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'MA 007', 'Paulina Villarreal', 0, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'Advanced survey of both standard and nonstandard non-operatic solo vocal repertoire of the United States, the British Isles, Italy, Germany, Austria, France, and other nations. Techniques and application of song study, musicianship, interpretation, performance practice, and program building.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 532', 'SONG LITERATURE IV', '9920', 'Closed', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'SM C141', 'Zachary Coates', 0, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Advanced survey of both standard and nonstandard, non-operatic solo vocal repertoire of the United States, the British Isles, Italy, Germany, Austria, France, and other nations. Techniques and application of song study, musicianship, interpretation, performance practice, and program building.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 533', 'SURVEY OF WIND LITERATURE AND PEDAGOGY FOR COLLABORATIVE PIANISTS', '33876', 'Class Status', 'MW Monday, Wednesday 2:20 PM–3:35 PM', 'JS 315', 'Anne Epperson, Aram Arakelyan', 1, NULL, 'Lecture', '3', 'EAST STUDIO BUILDING', ARRAY[]::TEXT[], 'A practical, analytical, and historical study of relevant woodwind and brass repertoire. Emphasis on sonata/duo, concerti and French conservatory pieces. Exploration of the pedagogical value of certain repertoire, the nature of the instruments and their pedagogy, and how these principles can be adapted to pianists.', ARRAY[]::TEXT[], NULL),
    ('MUS-M 535', 'MASTER''S SEMINAR IN CHORAL LITERATURE: RENAISSANCE TO 1700', '30304', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–12:25 PM', 'SM 271', 'Carolann Buff', 8, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'An analytical and contextual study of choral repertoire from liturgical beginnings through the early Baroque.', ARRAY[]::TEXT[], NULL),
