    ('MUS-O 501', 'FUNDAMENTALS OF JAZZ THEORY', '5480', 'Class Status', 'MW Monday, Wednesday 9:10 AM–10:00 AM', 'SM 242', 'Jeremy Allen', 6, NULL, 'Lecture', '1', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Jazz nomenclature, chord/scale relationships, basic chord progressions and voice leading. Examples from both jazz and classical repertoire will be given to show connections between the two idioms.', ARRAY[]::TEXT[], NULL),
    ('MUS-O 513', 'JAZZ LISTENING AND EAR TRAINING', '9683', 'Class Status', 'TuTh Tuesday, Thursday 3:00 PM–4:15 PM', 'SM 340', 'Luke Gillespie', 3, NULL, 'Lecture', '3', 'SIMON MSC LBR REC', ARRAY[]::TEXT[], 'Introduction to basic skills required of the jazz musician, including listening, ear training, and transcription of jazz solos and their stylistic analysis.', ARRAY[]::TEXT[], NULL),
    ('MUS-O 516', 'JAZZ ARRANGING 1', '4364', 'Class Status', 'MW Monday, Wednesday 3:10 PM–4:00 PM', 'MU 204', 'Brent Wallarab', 1, NULL, 'Lecture', '3', 'MERRILL HALL', ARRAY[]::TEXT[], 'Fundamentals of jazz arranging for small ensemble including orchestration, instrument ranges and transposition, form and structure, nomenclature, and part/score layout.', ARRAY[]::TEXT[], NULL),
    ('MUS-O 522', 'JAZZ IMPROVISATION 2', '3933', 'Class Status', 'MW Monday, Wednesday 11:35 AM–12:25 PM', 'MC 070', 'Luke Gillespie', 2, NULL, 'Lecture', '3', 'MUSICAL ARTS CENTER', ARRAY[]::TEXT[], 'Theory and technique of bebop and post-bop. Theory and techniques of jazz improvisation, including bebop and hard-bop harmonic, melodic and rhythmic devices. Practice and study techniques and aural skills in the bebop and hard-bop styles.', ARRAY[]::TEXT[], NULL),
    ('MUS-O 523', 'JAZZ IMPROVISATION 3', '6675', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–12:25 PM', 'MA 378', 'John Raymond', 17, NULL, 'Lecture', '3', 'MUSIC ADDITION', ARRAY[]::TEXT[], 'Advanced jazz rhythmic and harmonic techniques applied to improvisation and compositions for improvisation; contemporary jazz rhythmic practices such as note grouping, odd meters, and metric modulation applied to standard tunes. Harmonic substitution, superimposition, and slash chords. Various post-bebop approaches to improvisation.', ARRAY[]::TEXT[], NULL),
    ('MUS-O 550', 'JAZZ CHAMBER ENSEMBLE', '5280', 'Class Status', NULL, NULL, 'Thomas Walsh, Jeremy Allen', 42, NULL, 'Lecture', '0–1', NULL, ARRAY[]::TEXT[], 'Rehearsal and performance of jazz chamber music.', ARRAY[]::TEXT[], NULL),
