    ('SLHS-A 100', 'AMERICAN SIGN LANGUAGE LEVEL ONE', '10463', 'Closed', 'TuTh Tuesday, Thursday 11:10 AM–12:25 PM', 'WB WEB', 'Joseph Murray', 0, NULL, 'Lecture', '4', 'LINDLEY HALL', ARRAY[]::TEXT[], 'Introductory sign language course for students with no previous experience with sign language. Builds a good basic vocabulary of signs, teaches fingerspelling, introduces basic aspects of the grammar and the proper use of facial expression in sign language conversation. Includes exposure to deaf culture.', ARRAY['IUB GenEd World Language class'], NULL),
    ('SLHS-A 150', 'AMERICAN SIGN LANGUAGE LEVEL TWO', '10262', 'Closed', 'TuTh Tuesday, Thursday 12:45 PM–2:00 PM', 'BH 340', 'Dana Demeter', 0, NULL, 'Lecture', '4', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'Continues building receptive and expressive abilities developed in SLHS-A 100. Emphasizes the use of signing space, facial grammar, body postures, fluent fingerspelling, and continued vocabulary development. Introduces more complex grammatical structures. Includes further exposure to deaf culture.', ARRAY['IUB GenEd World Language class'], NULL),
    ('SLHS-A 150', 'AMERICAN SIGN LANGUAGE LEVEL TWO', '12284', 'Closed', 'TuTh Tuesday, Thursday 2:20 PM–3:35 PM', 'LH 008', 'Rob Loveless', 0, NULL, 'Lecture', '4', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'Continues building receptive and expressive abilities developed in SLHS-A 100. Emphasizes the use of signing space, facial grammar, body postures, fluent fingerspelling, and continued vocabulary development. Introduces more complex grammatical structures. Includes further exposure to deaf culture.', ARRAY['IUB GenEd World Language class'], NULL),
    ('SLHS-A 150', 'AMERICAN SIGN LANGUAGE LEVEL TWO', '14921', 'Closed', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'LH 008', 'Rob Loveless', 0, NULL, 'Lecture', '4', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'Continues building receptive and expressive abilities developed in SLHS-A 100. Emphasizes the use of signing space, facial grammar, body postures, fluent fingerspelling, and continued vocabulary development. Introduces more complex grammatical structures. Includes further exposure to deaf culture.', ARRAY['IUB GenEd World Language class'], NULL),
    ('SLHS-A 150', 'AMERICAN SIGN LANGUAGE LEVEL TWO', '34253', 'Closed', 'MW Monday, Wednesday 12:45 PM–2:00 PM', 'WY 101', 'Heath Goodall', 0, NULL, 'Lecture', '4', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'Continues building receptive and expressive abilities developed in SLHS-A 100. Emphasizes the use of signing space, facial grammar, body postures, fluent fingerspelling, and continued vocabulary development. Introduces more complex grammatical structures. Includes further exposure to deaf culture.', ARRAY['IUB GenEd World Language class'], NULL),
    ('SLHS-A 200', 'AMERICAN SIGN LANGUAGE LEVEL THREE', '10263', 'Class Status', 'MW Monday, Wednesday 12:45 PM–2:00 PM', 'BH 206', 'Laura M Smith', 1, NULL, 'Lecture', '3', 'BALLANTINE HALL', ARRAY[]::TEXT[], 'Emphasizes the development of conversational ability. Examines complex grammatical structures, emphasizing the ability to use these structures in conversation. Covers characteristics of the Deaf population and their cultural values.', ARRAY['IUB GenEd World Language class'], NULL),
