    ('SOAD-C 280', 'INTRODUCTION TO COMPREHENSIVE DESIGN', '11245', 'Class Status', 'TuTh Tuesday, Thursday 2:20 PM–5:05 PM', 'KH 016 KH 002', 'Beth Huffman', 7, NULL, 'Lecture', '3', 'KIRKWOOD HALL', ARRAY[]::TEXT[], 'Focuses on skill building across the spectrum of modalities: drawing, physical model building, and 3D modeling. Uses human-centered design strategies to explore how human perceptions and activities affect design decisions.', ARRAY['COLL (CASE) A&H Breadth of Inquiry credit'], NULL),
    ('SOAD-C 280', 'INTRODUCTION TO COMPREHENSIVE DESIGN', '12148', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'KH 002 KH 016', 'Beth Huffman', 9, NULL, 'Lecture', '3', 'KIRKWOOD HALL', ARRAY[]::TEXT[], 'Focuses on skill building across the spectrum of modalities: drawing, physical model building, and 3D modeling. Uses human-centered design strategies to explore how human perceptions and activities affect design decisions.', ARRAY['COLL (CASE) A&H Breadth of Inquiry credit'], NULL),
