    ('SOAD-S 531', 'GRADUATE PAINTING', '8222', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'HD TBA', 'Dominic Mangila', 9, NULL, 'Laboratory', '3', 'BLDG NOT ASSIGNED', ARRAY[]::TEXT[], 'Intensive directed study in Painting. For students admitted to the M.F.A. program in Painting.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 541', 'GRADUATE PRINTMAKING', '8259', 'Class Status', 'TuTh Tuesday, Thursday 2:20 PM–5:05 PM', 'AZ 134', 'Tracy Templeton', 5, NULL, 'Laboratory', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Intensive directed study in printmaking. For students admitted to the M.F.A. program in printmaking.', ARRAY[]::TEXT[], NULL),
