    ('SOAD-S 543', 'GRADUATE LITHOGRAPHY', '32799', 'Class Status', 'MW Monday, Wednesday 12:45 PM–3:30 PM', 'AZ 125', 'Jennifer Johnson', 5, NULL, 'Studio', '1–3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Advanced work in lithography for graduate students.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 549', 'MFA PRINTMAKING SEMINAR', '8224', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Deals with both theoretical and practical issues in contemporary art. Discussions will be based on selected readings, including relevant suggestions from the participants. Students will make presentations on the influences and development of their work as well as collaborative research.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 549', 'MFA PRINTMAKING SEMINAR', '12528', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Deals with both theoretical and practical issues in contemporary art. Discussions will be based on selected readings, including relevant suggestions from the participants. Students will make presentations on the influences and development of their work as well as collaborative research.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 549', 'MFA PRINTMAKING SEMINAR', '12529', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'FA 230', 'Malcolm Smith', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Deals with both theoretical and practical issues in contemporary art. Discussions will be based on selected readings, including relevant suggestions from the participants. Students will make presentations on the influences and development of their work as well as collaborative research.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 550', 'GRADUATE TOPICS IN GRAPHIC DESIGN', '14400', 'Class Status', 'MW Monday, Wednesday 9:10 AM–11:55 AM', 'FA 137', 'Carrie Hott', 9, NULL, 'Laboratory', '3', 'FINE ARTS', ARRAY[]::TEXT[], 'Professional problem solving in graphic design. Using a variety of mediums to communicate messages, students apply processes from printing to multimedia as appropriate for directed projects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 550', 'GRADUATE TOPICS IN GRAPHIC DESIGN', '14399', 'Closed', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'FA 137', 'Alexander Landerman', 0, NULL, 'Laboratory', '3', 'FINE ARTS', ARRAY[]::TEXT[], 'Professional problem solving in graphic design. Using a variety of mediums to communicate messages, students apply processes from printing to multimedia as appropriate for directed projects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 551', 'GRADUATE GRAPHIC DESIGN', '8260', 'Class Status', 'MW Monday, Wednesday 12:45 PM–3:30 PM', 'FA 240', 'Alexander Landerman, Carrie Hott', 3, NULL, 'Lecture', '3', 'FINE ARTS', ARRAY[]::TEXT[], 'Graphic design as an integral element of all visual communication media. Self-defined and assigned study to assure as wide as possible exposure to the problem-solving process.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 559', 'MFA GRAPHIC DESIGN SEMINAR', '8225', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Provides background on major graphic design movements, the design of the alphabet and type styles, the use of tools (printing press, wood cut, engraving, camera, airbrush, computer). Social and political forces such as industrial development and nationalism will be considered. Writings of theorists and historians will be reviewed.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 559', 'MFA GRAPHIC DESIGN SEMINAR', '12534', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Provides background on major graphic design movements, the design of the alphabet and type styles, the use of tools (printing press, wood cut, engraving, camera, airbrush, computer). Social and political forces such as industrial development and nationalism will be considered. Writings of theorists and historians will be reviewed.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 559', 'MFA GRAPHIC DESIGN SEMINAR', '12535', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'FA 230', 'Malcolm Smith', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Provides background on major graphic design movements, the design of the alphabet and type styles, the use of tools (printing press, wood cut, engraving, camera, airbrush, computer). Social and political forces such as industrial development and nationalism will be considered. Writings of theorists and historians will be reviewed.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 560', 'GRADUATE TOPICS IN CERAMICS', '8263', 'Class Status', 'MW Monday, Wednesday 9:10 AM–11:55 AM', 'FA 152', 'Ellen Kleckner', 4, NULL, 'Laboratory', '1–3', 'FINE ARTS', ARRAY[]::TEXT[], 'Further practice in advanced ceramic techniques. Instruction through lectures, demonstrations, and critiques. Topics vary by instructor and semester.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 560', 'GRADUATE TOPICS IN CERAMICS', '8264', 'Closed', 'TuTh Tuesday, Thursday 2:20 PM–5:05 PM', 'FA 152', 'Malcolm Smith', 0, NULL, 'Laboratory', '1–3', 'FINE ARTS', ARRAY[]::TEXT[], 'Further practice in advanced ceramic techniques. Instruction through lectures, demonstrations, and critiques. Topics vary by instructor and semester.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 561', 'GRADUATE CERAMICS', '8261', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'AZ A024', 'Jonathan Gamblin', 7, NULL, 'Laboratory', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Studio techniques: advanced practice in the use of clay for expression or functional ceramics purposes. Theory: clay and body compositions glaze; materials, oxides, glaze compositions and calculation, firing procedures.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 568', 'GRADUATE HISTORY OF CERAMICS', '30466', 'Class Status', 'MW Monday, Wednesday 12:45 PM–2:00 PM', 'AZ 130', 'Timothy Mather', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Emphasis on the historical development of pottery in individual cultures, as well as how one culture''s pottery has influenced another''s.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 569', 'MFA CERAMICS SEMINAR', '8235', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Discussions, critiques and research projects in ceramic art. *Required each semester for M.F.A. candidates in ceramics.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 569', 'MFA CERAMICS SEMINAR', '12539', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Discussions, critiques and research projects in ceramic art. *Required each semester for M.F.A. candidates in ceramics.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 569', 'MFA CERAMICS SEMINAR', '12540', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'FA 230', 'Malcolm Smith', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Discussions, critiques and research projects in ceramic art. *Required each semester for M.F.A. candidates in ceramics.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 570', 'GRADUATE TOPICS IN SCULPTURE', '14410', 'Closed', 'MW Monday, Wednesday 12:45 PM–3:30 PM', 'AZ A107', 'Michael Calway-Fagen', 0, NULL, 'Laboratory', '1–3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Advanced work in sculpture for qualified students working in the chosen materials. The course focuses on the development of ideas as manifest in sculptural form.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 571', 'GRADUATE SCULPTURE', '8236', 'Class Status', 'TuTh Tuesday, Thursday 2:20 PM–5:05 PM', 'AZ A107', 'Melanie Pennington', 10, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Intensive directed study in Sculpture. For students admitted to the M.F.A. program in sculpture.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 579', 'GRADUATE SCULPTURE SEMINAR', '8237', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Group critiques sessions and readings of contemporary sculptural issues. Students will engage in activities to prepare them for professional practice as sculptors. These activities will include preparing for job applications and proposals for commissions, residencies, or other professional activities.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 579', 'GRADUATE SCULPTURE SEMINAR', '12544', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Group critiques sessions and readings of contemporary sculptural issues. Students will engage in activities to prepare them for professional practice as sculptors. These activities will include preparing for job applications and proposals for commissions, residencies, or other professional activities.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 579', 'GRADUATE SCULPTURE SEMINAR', '12545', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'FA 230', 'Malcolm Smith', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Group critiques sessions and readings of contemporary sculptural issues. Students will engage in activities to prepare them for professional practice as sculptors. These activities will include preparing for job applications and proposals for commissions, residencies, or other professional activities.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 580', 'GRADUATE TOPICS IN METALSMITHING AND JEWELRY DESIGN', '8238', 'Class Status', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'FA 210', 'Angela Caldwell', 8, NULL, 'Laboratory', '1–3', 'FINE ARTS', ARRAY[]::TEXT[], 'Improves and expands knowledge and skills in metalsmithing and jewelry design through special topics utilizing advanced techniques, tools, and materials.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 581', 'GRADUATE METALSMITHING AND JEWELRY DESIGN', '8239', 'Class Status', 'MW Monday, Wednesday 12:45 PM–3:30 PM', 'FA 210', 'Nicole Jacquard', 9, NULL, 'Lecture', '3', 'FINE ARTS', ARRAY[]::TEXT[], 'Guidance directed toward developing a personal direction of creative expression, artistic aesthetic, and art philosophy, ranging in materials, techniques and subjects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 589', 'MFA METALSMITHING AND JEWELRY DESIGN SEMINAR', '8240', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Primarily for students enrolled in the Metals MFA program. Weekly meetings include; critiques of individual research, oral and written study, and special projects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 589', 'MFA METALSMITHING AND JEWELRY DESIGN SEMINAR', '12549', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Primarily for students enrolled in the Metals MFA program. Weekly meetings include; critiques of individual research, oral and written study, and special projects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 589', 'MFA METALSMITHING AND JEWELRY DESIGN SEMINAR', '12550', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'FA 230', 'Malcolm Smith', 6, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Primarily for students enrolled in the Metals MFA program. Weekly meetings include; critiques of individual research, oral and written study, and special projects.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 590', 'GRADUATE TOPICS IN PHOTOGRAPHY', '8265', 'Closed', 'TuTh Tuesday, Thursday 11:10 AM–1:55 PM', 'FA 023', 'Osamu Nakagawa', 0, NULL, 'Studio', '1–3', 'FINE ARTS', ARRAY[]::TEXT[], 'Emphasizes advanced conceptual and technical development in digital and traditional photographic media and the expansion of creative possibilities. Topics vary. May include topics as alternative processes, advanced Photoshop, documentary, artist book making, photographic theory, installation art, and darkroom practice.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 591', 'GRADUATE PHOTOGRAPHY', '8241', 'Class Status', 'TuTh Tuesday, Thursday 2:20 PM–5:05 PM', 'FA 020', 'David Ondrik', 5, NULL, 'Laboratory', '3', 'FINE ARTS', ARRAY[]::TEXT[], 'Intensive directed study in photography. For students admitted to the M.F.A. program in photography.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 599', 'MFA PHOTOGRAPHY SEMINAR', '8242', 'Class Status', 'TuTh Tuesday, Thursday 9:35 AM–10:50 AM', 'AZ 130', 'Carissa Carman', 4, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Primarily for graduate students in photography. Oral and written study of both theoretical and practical issues in the history, criticism and theory of photography. Discussions will be based on selected readings, including relevant suggestions from the participants.', ARRAY[]::TEXT[], NULL),
    ('SOAD-S 599', 'MFA PHOTOGRAPHY SEMINAR', '12555', 'Class Status', 'MW Monday, Wednesday 9:35 AM–10:50 AM', 'AZ 130', 'Caleb Weintraub', 3, NULL, 'Lecture', '3', 'STUDIO ARTS ANNEX', ARRAY[]::TEXT[], 'Primarily for graduate students in photography. Oral and written study of both theoretical and practical issues in the history, criticism and theory of photography. Discussions will be based on selected readings, including relevant suggestions from the participants.', ARRAY[]::TEXT[], NULL),
