    ('SPH-K 630', 'BIOMECHANICS OF HUM PERFORMNCE', '29477', 'Closed', NULL, NULL, 'Allison Gruber', 0, NULL, 'Lecture', '3', NULL, ARRAY[]::TEXT[], NULL, ARRAY[]::TEXT[], NULL),
    ('SPH-K 634', 'RESPIRATORY PHYSIOLOGY OF EXERCISE', '29478', 'Class Status', 'MW Monday, Wednesday 11:10 AM–12:25 PM', 'AD A151', 'Robert Chapman', 5, NULL, 'Lecture', '3', 'AUDITORIUM', ARRAY[]::TEXT[], 'A system approach to the pulmonary and respiratory responses to acute and chronic exercise. Emphasis on ventilatory and respiratory adaptations associated with athletic performance to physical activity in health and disease.', ARRAY[]::TEXT[], NULL),
